package com.bodylog.personal;
import android.app.*;import android.os.*;import android.Manifest;import android.content.*;import android.hardware.Camera;import android.graphics.*;import android.view.*;import android.widget.*;
public class BodyCameraActivity extends Activity implements SurfaceHolder.Callback {
 Camera camera; SurfaceView surface; ImageView previous;String pose;int cameraId=0;
 public void onCreate(Bundle b){super.onCreate(b);pose=BodyPhotoStore.normalPose(getIntent().getStringExtra("pose"));FrameLayout root=new FrameLayout(this);surface=new SurfaceView(this);root.addView(surface);surface.getHolder().addCallback(this);previous=new ImageView(this);previous.setScaleType(ImageView.ScaleType.FIT_CENTER);root.addView(previous,new FrameLayout.LayoutParams(-1,-1));String id=BodyPhotoStore.latest(this,pose);if(!id.isEmpty())try{String base64=BodyPhotoStore.imageData(this,id,900);byte[] bytes=android.util.Base64.decode(base64.split(",")[1],0);previous.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));previous.setAlpha(.3f);}catch(Exception e){}LinearLayout controls=new LinearLayout(this);controls.setOrientation(1);SeekBar opacity=new SeekBar(this);opacity.setMax(80);opacity.setProgress(30);opacity.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean u){previous.setAlpha(n/100f);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});controls.addView(opacity);Button take=new Button(this);take.setText("3초 후 촬영");take.setOnClickListener(v->new Handler().postDelayed(()->shot(),3000));controls.addView(take);root.addView(controls,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));setContentView(root);if(checkSelfPermission(Manifest.permission.CAMERA)!=0)requestPermissions(new String[]{Manifest.permission.CAMERA},10);}
 void shot(){if(camera==null)return;camera.takePicture(null,null,(bytes,c)->{String id=BodyPhotoStore.save(this,bytes,pose);Intent i=new Intent();i.putExtra("photoId",id);setResult(-1,i);finish();});}
 void startCamera(){if(checkSelfPermission(Manifest.permission.CAMERA)!=0)return;try{camera=Camera.open(cameraId);camera.setDisplayOrientation(90);camera.setPreviewDisplay(surface.getHolder());camera.startPreview();}catch(Exception ignored){}}
 public void surfaceCreated(SurfaceHolder h){startCamera();}public void surfaceChanged(SurfaceHolder h,int f,int w,int height){}public void surfaceDestroyed(SurfaceHolder h){release();}
 void release(){if(camera!=null){camera.release();camera=null;}}
 public void onRequestPermissionsResult(int r,String[] p,int[] grants){super.onRequestPermissionsResult(r,p,grants);if(grants.length>0&&grants[0]==0)startCamera();else finish();}
 protected void onPause(){release();super.onPause();}
}